INSERT INTO t_comment (id, product_id, user_id, content, rating, created_at) VALUES
('80000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000003', 'Camera quality is fantastic for the price.', 5, '2026-06-06 10:00:00'),
('80000000-0000-0000-0000-000000000002', '40000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000004', 'Wish it were in stock, heard good things.', 4, '2026-06-08 10:00:00'),
('80000000-0000-0000-0000-000000000003', '40000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000005', 'Blazing fast, but runs a bit warm under load.', 4, '2026-06-12 10:00:00'),
('80000000-0000-0000-0000-000000000004', '40000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000007', 'Perfect for travel, very light.', 5, '2026-07-16 10:00:00'),
('80000000-0000-0000-0000-000000000005', '40000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000008', 'Noise cancelling works great on flights.', 5, '2026-06-07 10:00:00'),
('80000000-0000-0000-0000-000000000006', '40000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000009', 'Colors are vivid, but the stand wobbles a little.', 3, '2026-06-17 10:00:00'),
('80000000-0000-0000-0000-000000000007', '40000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000010', 'Makes great coffee, easy to clean.', 5, '2026-07-03 10:00:00'),
('80000000-0000-0000-0000-000000000008', '40000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000011', 'Sharp knives, arrived well packaged.', 5, '2026-07-15 10:00:00'),
('80000000-0000-0000-0000-000000000009', '40000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000012', 'Noticeably cleaner air within a day.', 4, '2026-07-22 10:00:00'),
('80000000-0000-0000-0000-000000000010', '40000000-0000-0000-0000-000000000010', '10000000-0000-0000-0000-000000000003', 'Couldn''t put it down, great read.', 5, '2026-06-09 10:00:00'),
('80000000-0000-0000-0000-000000000011', '40000000-0000-0000-0000-000000000011', '10000000-0000-0000-0000-000000000004', 'Clear explanations, good for beginners.', 4, '2026-07-08 10:00:00'),
('80000000-0000-0000-0000-000000000012', '40000000-0000-0000-0000-000000000012', '10000000-0000-0000-0000-000000000005', 'Nice daily prompts, good paper quality.', 4, '2026-07-09 10:00:00'),
('80000000-0000-0000-0000-000000000013', '40000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000007', 'Fits true to size, good denim weight.', 4, '2026-06-17 10:00:00'),
('80000000-0000-0000-0000-000000000014', '40000000-0000-0000-0000-000000000014', '10000000-0000-0000-0000-000000000008', 'Soft and holds up after washing.', 5, '2026-06-17 10:00:00'),
('80000000-0000-0000-0000-000000000015', '40000000-0000-0000-0000-000000000015', '10000000-0000-0000-0000-000000000009', 'Kept me dry on a rainy hike.', 5, '2026-07-30 10:00:00'),
('80000000-0000-0000-0000-000000000016', '40000000-0000-0000-0000-000000000016', '10000000-0000-0000-0000-000000000010', 'Great ankle support, broke in quickly.', 5, '2026-06-25 10:00:00'),
('80000000-0000-0000-0000-000000000017', '40000000-0000-0000-0000-000000000017', '10000000-0000-0000-0000-000000000011', 'Good grip, a bit thin for hard floors.', 3, '2026-06-25 10:00:00'),
('80000000-0000-0000-0000-000000000018', '40000000-0000-0000-0000-000000000018', '10000000-0000-0000-0000-000000000012', 'Easy setup, held up in light wind.', 4, '2026-07-30 10:00:00'),
('80000000-0000-0000-0000-000000000019', '40000000-0000-0000-0000-000000000019', '10000000-0000-0000-0000-000000000003', 'Kids loved it, pieces are sturdy.', 5, '2026-06-30 10:00:00'),
('80000000-0000-0000-0000-000000000020', '40000000-0000-0000-0000-000000000020', '10000000-0000-0000-0000-000000000004', 'Fun for family game night.', 4, '2026-06-30 10:00:00');
